// src/lib/llms.ts — the llms.txt writer (generated by Willo; deterministic, no LLM).
//
// Pure functions only: no Astro, no filesystem. src/pages/llms.txt.ts gathers
// the site's own facts at build time (identity from site-config, page titles
// from src/pages, entries from the content collections) and hands them here,
// so CMS edits and added entries reach /llms.txt on the next deploy without
// anyone regenerating a file. Format: https://llmstxt.org — an H1 name, a
// blockquote summary, then H2 sections of `- [title](url): note` links.

export interface LlmsLink {
  title: string;
  url: string;
  description?: string;
}

export interface LlmsSection {
  heading: string;
  links: LlmsLink[];
}

export interface LlmsDoc {
  name: string;
  description?: string;
  details?: string;
  sections: LlmsSection[];
}

/** One collection's entry, already resolved to its public URL. */
export interface LlmsEntry {
  title: string;
  url: string;
  description?: string;
  date?: Date;
}

/** The input contract for one collection section (reused by the migration
 * engine's routed collections — PLAN-website-migration R2-b-h-9). */
export interface LlmsCollection {
  label: string;
  /** The collection's index page, when the site has one. */
  indexUrl?: string;
  entries: LlmsEntry[];
}

export const LLMS_LIMITS = {
  pages: 60,
  entriesPerCollection: 25,
  collections: 12,
  links: 250,
  title: 120,
  description: 160,
} as const;

const SEPARATORS = '[-\\u2013\\u2014|:\\u00b7\\u2022]';
const SPACED_SEPARATOR = new RegExp(`\\s+${SEPARATORS}+\\s+`, 'g');
// Spaced separators only: "Home-Grown Farms" and "Sweet-Home" are names.
const HOME_PREFIX = new RegExp(`^home\\s+${SEPARATORS}+\\s+`, 'i');
const HOME_SUFFIX = new RegExp(`\\s+${SEPARATORS}+\\s+home$`, 'i');
const PLACEHOLDER_NAMES = new Set(['', 'your business', 'your new business']);
// The scaffold's stand-in description ("<name> — an AI-powered business").
const PLACEHOLDER_DESCRIPTION = /—\s*an AI-powered business\s*$/i;

export function oneLine(value: unknown, max: number): string {
  if (typeof value !== 'string') return '';
  // Capped before any regex runs: CMS text and page sources are unbounded.
  const text = value
    .slice(0, max * 8 + 1000)
    .replace(/<[^<>]*>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#0?39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();
  if (text.length <= max) return text;
  const cut = text.slice(0, max - 1);
  const space = cut.lastIndexOf(' ');
  return `${(space > max * 0.6 ? cut.slice(0, space) : cut).replace(/[\s,;:.-]+$/, '')}…`;
}

/** A site name as a crawler should read it: never a page title such as
 * "Home - Acme". A crawled home `<title>` became the identity on some
 * migrated sites, so a leading or trailing "Home" segment is dropped. */
export function cleanSiteName(name: unknown): string {
  const text = oneLine(name, 200);
  const stripped = text.replace(HOME_PREFIX, '').replace(HOME_SUFFIX, '').trim();
  return stripped || text;
}

export function isPlaceholderName(name: string): boolean {
  return PLACEHOLDER_NAMES.has(name.trim().toLowerCase());
}

export function isPlaceholderDescription(text: string): boolean {
  return !text.trim() || PLACEHOLDER_DESCRIPTION.test(text);
}

/** "About | Acme" → "About": drop the site-name affix every page repeats,
 * with any tagline riding after it ("Contact | Acme | Top Law Firm" →
 * "Contact"). Segments split only on a spaced separator, so "Pre-AIA" stays
 * one word. */
export function stripSiteAffix(title: string, siteName: string): string {
  const clean = oneLine(title, 300);
  const name = siteName.trim().toLowerCase();
  if (!name) return clean;
  // Cut the original string at the separator, so the rest keeps its own.
  const seps = [...clean.matchAll(SPACED_SEPARATOR)].map((m) => [m.index ?? 0, (m.index ?? 0) + m[0].length]);
  for (let i = 0; i <= seps.length; i += 1) {
    const lo = i === 0 ? 0 : seps[i - 1][1];
    const hi = i === seps.length ? clean.length : seps[i][0];
    if (clean.slice(lo, hi).trim().toLowerCase() !== name) continue;
    if (i > 0) return clean.slice(0, seps[i - 1][0]).trim() || clean;
    if (seps.length) return clean.slice(seps[0][1]).trim() || clean;
  }
  return clean;
}

/** "practice_area" / "our-team" → "Practice Area" / "Our Team". */
export function humanize(slug: string): string {
  const words = slug
    .replace(/\.[a-z0-9]+$/i, '')
    .split(/[-_\s/]+/)
    .filter(Boolean);
  return words.map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
}

function linkText(text: string): string {
  return text.replace(/\\/g, '\\\\').replace(/\[/g, '\\[').replace(/\]/g, '\\]');
}

function linkUrl(url: string): string {
  return url.replace(/[\u0000-\u001f\u007f]/g, '').replace(/ /g, '%20').replace(/\(/g, '%28').replace(/\)/g, '%29');
}

/** One collection as an llms.txt section: its index first, then up to
 * `limit` entries, newest first when they are dated, else by title. */
export function collectionSection(
  collection: LlmsCollection,
  limit: number = LLMS_LIMITS.entriesPerCollection,
): LlmsSection {
  const entries = collection.entries.filter((e) => e.title && e.url);
  const dated = entries.filter((e) => e.date && !Number.isNaN(e.date.valueOf())).length;
  const sorted = [...entries].sort((a, b) =>
    dated * 2 >= entries.length && dated > 0
      ? (b.date?.valueOf() ?? 0) - (a.date?.valueOf() ?? 0)
      : a.title.localeCompare(b.title),
  );
  const links: LlmsLink[] = [];
  if (collection.indexUrl) {
    links.push({
      title: collection.label,
      url: collection.indexUrl,
      description: `index of all ${entries.length} ${entries.length === 1 ? 'entry' : 'entries'}`,
    });
  }
  // Entries that read the same (title and note) tell a crawler nothing new —
  // e.g. one "Our Attorneys" page per letter of the alphabet.
  const seen = new Set<string>();
  for (const entry of sorted) {
    if (links.length - (collection.indexUrl ? 1 : 0) >= limit) break;
    const key = `${entry.title.toLowerCase()}\u0000${entry.description ?? ''}`;
    if (seen.has(key)) continue;
    seen.add(key);
    links.push({ title: entry.title, url: entry.url, description: entry.description });
  }
  return { heading: collection.label, links };
}

/** Render the document. Bounded: every title and note is one capped line,
 * and the whole file carries at most `LLMS_LIMITS.links` links. */
export function renderLlmsTxt(doc: LlmsDoc): string {
  const out: string[] = [`# ${oneLine(doc.name, LLMS_LIMITS.title) || 'Website'}`];
  const description = oneLine(doc.description, 500);
  if (description) out.push('', `> ${description}`);
  const details = oneLine(doc.details, 500);
  if (details) out.push('', details);
  let budget: number = LLMS_LIMITS.links;
  for (const section of doc.sections) {
    if (budget <= 0) break;
    const lines: string[] = [];
    for (const link of section.links) {
      if (budget <= 0) break;
      const title = oneLine(link.title, LLMS_LIMITS.title);
      if (!title || !link.url) continue;
      const note = oneLine(link.description, LLMS_LIMITS.description);
      lines.push(`- [${linkText(title)}](${linkUrl(link.url)})${note ? `: ${note}` : ''}`);
      budget -= 1;
    }
    if (lines.length) out.push('', `## ${oneLine(section.heading, LLMS_LIMITS.title)}`, '', ...lines);
  }
  return `${out.join('\n')}\n`;
}

export interface PageMeta {
  title?: string;
  description?: string;
  noindex: boolean;
}

// A JS string literal at `src[i]` → [value, index after it], or null.
function readJsString(src: string, i: number): [string, number] | null {
  const quote = src[i];
  if (quote !== '"' && quote !== "'" && quote !== '`') return null;
  let out = '';
  for (let j = i + 1; j < src.length; j += 1) {
    const ch = src[j];
    if (ch === '\\') {
      const next = src[j + 1] ?? '';
      if (next === 'u' && /^[0-9a-fA-F]{4}$/.test(src.slice(j + 2, j + 6))) {
        out += String.fromCharCode(parseInt(src.slice(j + 2, j + 6), 16));
        j += 5;
      } else {
        out += next === 'n' ? ' ' : next === 't' ? ' ' : next;
        j += 1;
      }
      continue;
    }
    if (quote === '`' && ch === '$' && src[j + 1] === '{') return null;
    if (ch === quote) return [out, j + 1];
    out += ch;
  }
  return null;
}

function frontmatterOf(source: string): string {
  const m = /^\s*---\r?\n([\s\S]*?)\r?\n---/.exec(source);
  return m ? m[1] : '';
}

function constString(frontmatter: string, name: string): string | undefined {
  const m = new RegExp(`(?:const|let)\\s+${name}\\s*(?::\\s*string\\s*)?=\\s*`).exec(frontmatter);
  if (!m) return undefined;
  return readJsString(frontmatter, m.index + m[0].length)?.[0];
}

// Template comments (`{/* … */}`, `<!-- … -->`) removed in one linear pass,
// so a commented-out `<Base title="Old" noindex>` is not read as the page's.
function stripComments(body: string): string {
  let out = '';
  let i = 0;
  // Next position of each opener, recomputed only once `i` has passed it.
  let jsx = -2;
  let html = -2;
  while (i < body.length) {
    if (jsx !== -1 && jsx < i) jsx = body.indexOf('{/*', i);
    if (html !== -1 && html < i) html = body.indexOf('<!--', i);
    const at = jsx < 0 ? html : html < 0 ? jsx : Math.min(jsx, html);
    if (at < 0) {
      out += body.slice(i);
      break;
    }
    out += body.slice(i, at);
    const close = at === jsx ? body.indexOf('*/}', at + 3) : body.indexOf('-->', at + 4);
    if (close < 0) break;
    i = close + 3;
  }
  return out;
}

// `title=` / `description=` / `noindex` on the page's layout tag (`<Base …>`).
function layoutAttributes(source: string): Map<string, string | boolean | null> {
  // null = present but not statically knowable (`{expr}`, a `{...spread}`).
  const attrs = new Map<string, string | boolean | null>();
  const body = stripComments(source.replace(/^\s*---\r?\n[\s\S]*?\r?\n---/, ''));
  const tag = /<(Base|(?:[A-Z][A-Za-z0-9]*)?Layout)\b/.exec(body);
  if (!tag) return attrs;
  const frontmatter = frontmatterOf(source);
  let i = tag.index + tag[0].length;
  while (i < body.length) {
    while (/\s/.test(body[i] ?? '')) i += 1;
    const ch = body[i];
    if (ch === undefined || ch === '>' || (ch === '/' && body[i + 1] === '>')) break;
    const nameMatch = /^[A-Za-z_:][-A-Za-z0-9_:.]*/.exec(body.slice(i));
    if (!nameMatch) {
      if (ch === '{') {
        // A spread `{...props}` could carry anything, noindex included.
        attrs.set('...', null);
        let depth = 0;
        for (; i < body.length; i += 1) {
          if (body[i] === '{') depth += 1;
          else if (body[i] === '}' && --depth === 0) { i += 1; break; }
        }
        continue;
      }
      i += 1;
      continue;
    }
    const name = nameMatch[0];
    i += name.length;
    while (/\s/.test(body[i] ?? '')) i += 1;
    if (body[i] !== '=') { attrs.set(name, true); continue; }
    i += 1;
    while (/\s/.test(body[i] ?? '')) i += 1;
    if (body[i] === '"' || body[i] === "'") {
      const close = body.indexOf(body[i], i + 1);
      if (close < 0) break;
      attrs.set(name, body.slice(i + 1, close));
      i = close + 1;
    } else if (body[i] === '{') {
      let depth = 0;
      const open = i;
      for (; i < body.length; i += 1) {
        const c = body[i];
        if (c === '"' || c === "'" || c === '`') {
          const lit = readJsString(body, i);
          if (lit) { i = lit[1] - 1; continue; }
        }
        if (c === '{') depth += 1;
        else if (c === '}' && --depth === 0) { i += 1; break; }
      }
      const expr = body.slice(open + 1, i - 1).trim();
      const lit = readJsString(expr, 0);
      if (lit && lit[1] === expr.length) attrs.set(name, lit[0]);
      else if (expr === 'true' || expr === 'false') attrs.set(name, expr === 'true');
      else {
        const resolved = /^[A-Za-z_$][\w$]*$/.test(expr) ? constString(frontmatter, expr) : undefined;
        attrs.set(name, resolved ?? null);
      }
    } else {
      i += 1;
    }
  }
  return attrs;
}

function yamlValue(frontmatter: string, key: string): string | undefined {
  const m = new RegExp(`^${key}[ \\t]*:[ \\t]*(.+)$`, 'm').exec(frontmatter);
  if (!m) return undefined;
  const raw = m[1].trim();
  if (raw.startsWith('"')) {
    try { return JSON.parse(raw); } catch { return raw.slice(1, -1); }
  }
  if (raw.startsWith("'")) return raw.slice(1, -1).replace(/''/g, "'");
  return raw;
}

const ORG_TYPES = ['Organization', 'LocalBusiness', 'Corporation', 'LegalService', 'WebSite'];

/** The description a page's own JSON-LD gives the business — the
 * Organization (or a subtype), else the WebSite node. Migrated pages carry
 * the source's structured data verbatim, so this is the source site's own
 * words when nothing else describes it. */
export function jsonLdDescription(source: string): string | undefined {
  const found: Array<{ rank: number; text: string }> = [];
  const visit = (node: any) => {
    if (Array.isArray(node)) return node.forEach(visit);
    if (!node || typeof node !== 'object') return;
    const types = ([] as unknown[]).concat(node['@type'] ?? []);
    const rank = Math.min(
      ...types.map((t) => (typeof t === 'string' && ORG_TYPES.includes(t) ? (t === 'WebSite' ? 1 : 0) : 9)),
      9,
    );
    if (rank < 9 && typeof node.description === 'string' && node.description.trim()) {
      found.push({ rank, text: node.description });
    }
    if (node['@graph']) visit(node['@graph']);
  };
  for (const m of source.matchAll(/set:html=\{/g)) {
    const lit = readJsString(source, (m.index ?? 0) + m[0].length);
    if (!lit) continue;
    try {
      visit(JSON.parse(lit[0]));
    } catch {
      // not JSON-LD
    }
  }
  return found.sort((a, b) => a.rank - b.rank)[0]?.text;
}

// `name="robots"` (or a crawler-specific name), as an attribute of its own —
// not `data-name=`, not `robots-ai`.
const ROBOTS_NAME = /(?:^|\s)name\s*=(?:\s*\{)?\s*["'`]?(?:robots|googlebot|bingbot|gptbot|claudebot|google-extended)(?=["'`}\s>/]|$)/i;

/** Whether any robots meta tag in the source says `noindex` (or `none`). The
 * tags are collected first with a pattern that cannot backtrack across a
 * page, then each one is read on its own. */
export function robotsNoindex(source: string): boolean {
  for (const m of source.matchAll(/<meta\b[^<>]*>/gi)) {
    // A real meta tag is short; capping each one bounds the attribute reads.
    const tag = m[0].slice(0, 2048);
    if (!ROBOTS_NAME.test(tag)) continue;
    const content = /\bcontent\s*=\s*(\{)?\s*(?:"([^"]*)"|'([^']*)'|`([^`]*)`|([^\s>]*))/i.exec(tag);
    if (!content) continue;
    const literal = content[2] ?? content[3] ?? content[4];
    // An expression (`content={robots}`) cannot be read: fail closed.
    if (literal === undefined && content[1]) return true;
    const tokens = (literal ?? content[5] ?? '').toLowerCase().split(/[\s,]+/);
    if (tokens.includes('noindex') || tokens.includes('none')) return true;
  }
  return false;
}

// A literal attribute value on a tag: `a="x"`, `a='x'`, `a={"x"}`, or bare.
function tagAttr(tag: string, name: string): string | undefined {
  const m = new RegExp(
    `(?:^|\\s)${name}\\s*=(\\s*\\{)?\\s*(?:"([^"]*)"|'([^']*)'|\`([^\`]*)\`|([^\\s>{}"'\`]+))`,
    'i',
  ).exec(tag);
  if (!m) return undefined;
  // `{expr}`: not a literal, so not something this page can be held to.
  if (m[1] && m[5] !== undefined) return undefined;
  return m[2] ?? m[3] ?? m[4] ?? m[5];
}

function samePath(href: string, pagePath: string): boolean {
  try {
    const norm = (p: string) => decodeURI(p).replace(/\/index\.html$/, '/').replace(/\.html$/, '').replace(/\/+$/, '') || '/';
    return norm(new URL(href, new URL(pagePath, 'file:///')).pathname) === norm(pagePath);
  } catch {
    return true; // unreadable: not evidence the page points elsewhere
  }
}

/** Whether the page says another URL is the real one: a canonical link to a
 * different path, or a meta-refresh redirect. The same signals the sitemap
 * hygiene pass (astro.config.mjs, PR #1922) prunes on, read from the page
 * source, so /llms.txt and /sitemap.xml agree. Path only, never host. */
export function pointsElsewhere(source: string, pagePath: string): boolean {
  for (const m of source.matchAll(/<(link|meta)\b[^<>]*>/gi)) {
    const tag = m[0].slice(0, 2048);
    if (m[1].toLowerCase() === 'link') {
      const rel = (tagAttr(tag, 'rel') ?? '').toLowerCase().split(/\s+/);
      const href = tagAttr(tag, 'href');
      if (rel.includes('canonical') && href && !samePath(href, pagePath)) return true;
    } else if ((tagAttr(tag, 'http-equiv') ?? '').toLowerCase() === 'refresh') {
      const url = /url\s*=\s*['"]?([^'"]+)/i.exec(tagAttr(tag, 'content') ?? '');
      if (url && !samePath(url[1].trim(), pagePath)) return true;
    }
  }
  return false;
}

/** The title, description and noindex flag a page passes to its layout.
 * Fails closed: a `noindex` (or spread) whose value is not statically
 * `false` counts as noindex, so a page the owner hid is never listed. */
export function pageMeta(source: string, ext: string, pagePath?: string): PageMeta {
  const hidden = robotsNoindex(source) || (pagePath !== undefined && pointsElsewhere(source, pagePath));
  if (ext === 'md' || ext === 'mdx') {
    const fm = frontmatterOf(source);
    return {
      title: yamlValue(fm, 'title'),
      description: yamlValue(fm, 'description'),
      noindex: hidden || /^noindex\s*:\s*(?:true|yes)\s*$/im.test(fm),
    };
  }
  const attrs = layoutAttributes(source);
  const text = (key: string) => {
    const v = attrs.get(key);
    return typeof v === 'string' ? v : undefined;
  };
  const flag = attrs.get('noindex');
  const noindex = attrs.has('noindex') ? flag !== false && flag !== 'false' : attrs.has('...');
  return {
    title: text('title'),
    description: text('description'),
    noindex: hidden || noindex,
  };
}
